from format_lecon import Lesson,paras,table,steps
from medicaments import quote
l=Lesson('Ésotropie infantile',3)
bot=l.subwindow('toxine','Toxine botulique : limite de l’indication suisse',paras('La toxine botulique est une option discutée dans certains centres pour l’ésotropie infantile. L’usage chez le nourrisson est hors information professionnelle suisse de BOTOX. Il ne faut pas transposer les doses adultes ou confondre les unités de spécialités différentes.')+quote('52433',["· traitement symptomatique du blépharospasme", "Il n'existe aucune étude sur la sécurité et l'efficacité du BOTOX dans le traitement du blépharospasme", "· Hypersensibilité connue à la substance active", "· Présence d'une infection au niveau", "Le risque potentiel pour l'homme est inconnu. BOTOX", "On ne sait pas si BOTOX passe"])+paras('Ces extraits définissent les limites de la spécialité, pas une prescription pour l’enfant. La discussion relève d’une équipe expérimentée, avec information des parents, évaluation des alternatives et suivi. Un ptosis ou une nouvelle déviation peut suivre l’injection ; dysphagie, faiblesse générale ou difficulté respiratoire imposent un avis urgent.', 'Aucune dose de nourrisson validée par cette notice n’est fournie. La comparaison entre chirurgie et toxine dans la revue Cochrane2023 repose sur des données de très faible certitude ; elle ne justifie ni une supériorité universelle ni une procédure non surveillée.'),(15,18))
l.add('L’{ésotropie infantile est une convergence constante installée avant six mois}. Cette définition est celle du guide RCOphth de 2012. Le terme congénital ne prouve pas que la déviation était déjà visible à la naissance.',paras('Il s’agit d’un syndrome d’installation précoce avec altération du développement binoculaire. Le diagnostic repose sur l’histoire et l’examen ; il ne se résume pas à l’âge ou à la grandeur de l’angle.', 'Une ésotropie accommodative très précoce, une paralysie du VI ou une mauvaise vision d’origine organique peuvent l’imiter. Une convergence intermittente fugace du nouveau-né ne doit pas être confondue avec une déviation constante persistante.'),(1,3))
l.add('Le {risque principal concerne le développement visuel précoce}. Une amblyopie peut apparaître, surtout si un œil fixe toujours. Des anomalies verticales ou un nystagmus peuvent se manifester plus tard.',paras('Aucune incidence suisse contemporaine propre à cette entité n’est établie dans les sources consultées. Les estimations anciennes du guide britannique ne sont pas reprises comme données nationales.', 'La fixation alternante peut préserver une acuité relativement symétrique tout en laissant une vision binoculaire anormale. Une bonne fixation de chaque œil ne prouve donc pas une stéréoscopie normale.', 'Le pronostic dépend de la fonction visuelle, de l’ancienneté du désalignement et de la réponse au traitement. Les études ne déterminent pas un âge opératoire optimal universel ; l’incertitude ne justifie pas de retarder l’évaluation d’un nourrisson.'),(2,3,18))
l.add('Le {désalignement précoce perturbe l’apprentissage binoculaire}. Les images ne se combinent pas normalement durant une période sensible. La fixation croisée peut donner une fausse impression de paralysie.',table(['Perturbation','Examen utile','Conséquence thérapeutique'],[['La déviation empêche une coopération binoculaire stable.','Mesurer l’angle et apprécier la fixation de chaque œil.','Planifier un alignement adapté tout en surveillant la vision.'],['L’enfant utilise l’œil droit pour regarder à gauche et inversement.','Examiner les ductions après adaptation de la fixation.','Ne pas conclure à une paralysie bilatérale du VI sur la seule fixation croisée.'],['Une fixation prédominante pénalise l’autre œil.','Comparer acuités ou comportement de fixation.','Corriger la réfraction et traiter l’amblyopie.'],['Une anomalie verticale ou un nystagmus accompagne le syndrome.','Observer les mouvements dans différentes positions et sous occlusion.','Adapter les objectifs et la stratégie chirurgicale.']])+paras('La cause précise reste souvent indéterminée. Une explication par un muscle simplement trop fort serait insuffisante : le développement sensorimoteur, la fusion et les adaptations de fixation interviennent.'),(3,6))
l.add('Le {bilan exclut d’abord une maladie oculaire ou neurologique}. Une leucocorie ou une anomalie du fond d’œil change immédiatement la priorité. Une limitation motrice vraie demande une exploration spécifique.',paras('Le rétinoblastome et les autres causes de mauvaise vision peuvent provoquer un strabisme sensoriel ; l’examen organique reste obligatoire. Une anomalie de la papille, une baisse visuelle ou des signes neurologiques ne sont pas expliqués par l’étiquette infantile.', 'Une paralysie du VI empêche l’abduction, alors que la fixation croisée peut seulement la masquer. Le syndrome de Duane peut comporter une rétraction du globe et un rétrécissement de la fente palpébrale. Une composante accommodative précoce se recherche par la réfraction et la réponse aux lunettes.', 'Les signes d’hypertension intracrânienne ou une déviation nouvellement acquise imposent le tri urgent du cours général. Ne pas attendre une opération d’alignement pour établir la cause.'),(3,4,6,9,10))
l.add('L’{anamnèse reconstitue l’ancienneté sans supposer un début congénital}. Les parents décrivent la constance et l’alternance de fixation. Les photographies, le développement et les antécédents périnataux complètent le récit.',paras('Demander quand la déviation a été remarquée et si elle était constante. Une photographie peut aider à documenter une période, sans prouver à elle seule l’alignement exact.', 'Recueillir prématurité, complications périnatales, retard ou régression du développement, antécédents familiaux et maladies oculaires. Des troubles du développement peuvent modifier les moyens d’examen et la prise en charge.', 'Interroger comportement visuel, poursuite, intérêt pour les visages et préférence d’un œil. Un reflet blanc, une douleur, des vomissements ou une modification neurologique accélèrent l’orientation.'),(1,3,4))
l.add('L’{examen recherche fixation alternante, angle et mouvements complets}. Le normal attendu dépend de l’âge et de la coopération. Une impossibilité de mesurer ne vaut jamais un résultat normal.',paras('Observer le nourrisson dans une position confortable, avec une cible adaptée. Comparer les reflets cornéens puis utiliser le test à l’écran lorsque la fixation le permet. Mesurer avec des prismes dès que possible et documenter la méthode.', 'La fixation croisée peut dissimuler l’abduction : l’examinateur adapte l’occlusion et la présentation de la cible. Ne pas forcer la tête ni multiplier des manœuvres inconfortables sans nécessité. Si le doute persiste, reprendre le bilan spécialisé.', 'Rechercher nystagmus latent ou manifeste-latent, élévation en adduction, déviation verticale dissociée et posture. Contrôler pupilles, segment antérieur et fond d’œil, puis réfraction selon une stratégie de cycloplégie adaptée au nourrisson.'),(3,6))
l.add('Les {associations sensorimotrices doivent être décrites séparément}. Une grande convergence n’est qu’un élément du syndrome. L’amblyopie, le nystagmus et les déviations verticales modifient le suivi.',paras('7.1. Le syndrome horizontal associe déviation constante et fixation souvent croisée. La limitation apparente doit être distinguée d’un déficit véritable.', '7.2. Le syndrome sensoriel comporte perte de coopération binoculaire et parfois amblyopie. Il se recherche par la fixation et les tests d’acuité adaptés, puis par les tests sensoriels lorsque l’âge le permet.', '7.3. Les anomalies associées peuvent comprendre nystagmus et déviation verticale dissociée, où un œil s’élève dans certaines conditions de dissociation. Le spécialiste les documente car elles peuvent apparaître ou évoluer après l’alignement horizontal.'),(3,))
l.add('Le {diagnostic est clinique après exclusion des imitateurs}. Retenir l’installation précoce constante et le profil oculomoteur. La réfraction et l’examen organique restent indispensables.',paras('La définition RCOphth2012 utilise la constance avant six mois. La revue Cochrane2023 étudie également l’ésotropie survenue durant les six premiers mois. Il ne faut pas transformer une date approximative rapportée en certitude biologique.', 'Un angle large, une fixation croisée et des signes associés renforcent l’hypothèse. Aucun signe isolé ne suffit à éliminer une cause sensorielle ou nerveuse. Une réponse importante à la correction optique conduit à reconsidérer la composante accommodative.'),(3,6,18))
l.add('Les {examens précisent la vision et recherchent une cause associée}. La référence est le bilan ophtalmologique pédiatrique. L’imagerie répond à une anomalie, pas au seul mot infantile.',paras('9.a. L’examen clinique répété caractérise le syndrome et sa trajectoire. Il n’existe pas de test biologique confirmatoire unique.', '9.b. Évaluer fixation, réfraction cycloplégique, pupilles et fond d’œil. La notice suisse Cyclogyl indique de ne pas l’utiliser avant un an ; le schéma britannique historique ne peut pas être transposé au nourrisson.', '9.c. Adapter les tests d’acuité au développement et répéter un examen insuffisant. Une anesthésie pour examen complet relève d’une indication spécialisée, notamment si une cause organique ne peut être exclue.', '9.d. Une anomalie neurologique, une atteinte du nerf optique, une limitation vraie ou une baisse visuelle inexpliquée motive un bilan et éventuellement une imagerie ciblée.')+table(['Résultat','Interprétation','Action'],[['Les ductions sont complètes malgré une fixation croisée.','La pseudo-limitation ne prouve pas une paralysie.','Poursuivre la caractérisation du syndrome infantile.'],['La vision est nettement asymétrique.','Une amblyopie ou une lésion organique est possible.','Examiner la cause et traiter la vision.'],['Une déviation diminue nettement sous correction.','Une composante accommodative est présente.','Adapter la classification et les objectifs opératoires.'],['Le fond d’œil ou la neurologie est anormal.','Une cause associée doit être explorée.','Accélérer le bilan spécialisé.']]),(3,4,6,7))
l.add('L’{algorithme commence par la sécurité visuelle et neurologique}. Mesurer la réfraction et traiter l’amblyopie. Discuter ensuite l’alignement avec l’équipe pédiatrique spécialisée.',steps('Écarter leucocorie, lésion oculaire, déficit neurologique et paralysie véritable.', 'Confirmer l’ancienneté et caractériser fixation, angle, réfraction et signes associés.', 'Prescrire la correction utile et le traitement d’amblyopie avec contrôle rapproché adapté.', 'Discuter le calendrier et les objectifs de chirurgie sans promettre une stéréoscopie normale.', 'Maintenir la surveillance de l’acuité et des composantes horizontales et verticales après traitement.'),(1,3,6,18))
l.add('La {prise en charge associe développement visuel et alignement}. La chirurgie est fréquemment discutée après le bilan optique et sensoriel. L’âge et la technique se décident individuellement.',paras('11.A. Chercher une bonne acuité de chaque œil, un alignement utile et le meilleur potentiel binoculaire possible. Expliquer qu’une vision en relief normale n’est pas garantie.', '11.B. Corriger la réfraction pertinente et traiter une amblyopie avant et après l’intervention selon les besoins. La chirurgie agit sur les muscles ; la décision s’appuie sur mesures répétées, stabilité et contexte. La revue Cochrane2023 ne résout pas les controverses sur le meilleur âge ou la meilleure technique.', '11.B. Une option injectable peut être discutée dans des cas sélectionnés : '+bot, '11.C. Une mauvaise vision inexpliquée ou une nouvelle alarme déclenche un bilan causal. Après intervention, douleur importante, rougeur croissante ou baisse visuelle demandent une évaluation rapide plutôt qu’un simple ajustement de l’occlusion.', '11.D. Organiser l’accompagnement des parents, les contrôles et l’adaptation du traitement visuel. La sortie après anesthésie répond aux critères pédiatriques de l’équipe ; le retour à domicile demande un adulte responsable, des consignes comprises et un accès aux soins. Une récidive ou une composante verticale peut nécessiter une nouvelle intervention, sans signifier que le suivi antérieur était inutile.'),(1,3,6,15,18))
l.add('La {prévention limite surtout le retard diagnostique et l’amblyopie}. Une convergence constante précoce doit être examinée. Les contrôles restent nécessaires après l’alignement.',paras('Aucune prévention primaire spécifique n’est démontrée pour toutes les formes essentielles. La prévention secondaire repose sur l’observation parentale et les contrôles visuels pédiatriques.', 'La prévention tertiaire vérifie acuité, lunettes et récidive. Les parents doivent savoir que l’absence de plainte ne remplace pas l’examen de chaque œil et que l’aspect droit après chirurgie ne justifie pas l’arrêt spontané du traitement visuel.'),(1,2,3,6))
l.add('Les {points clés distinguent âge de début, cause et pronostic}. La fixation croisée peut imiter une paralysie. La chirurgie d’alignement et le traitement de l’amblyopie poursuivent des objectifs complémentaires.',paras('Examiner le fond d’œil avant de retenir une forme essentielle. Ne pas transposer Cyclogyl au nourrisson à partir d’un guide étranger. Ne pas présenter la toxine chez le nourrisson comme une indication autorisée de BOTOX. Informer des incertitudes du calendrier opératoire sans retarder l’évaluation.'),(3,7,15,18))
l.quiz([('Infantile signifie-t-il nécessairement visible dès la naissance ?','Non.'),('Quel repère définit la forme dans le guide cité ?','Une ésotropie constante avant six mois.'),('Une fixation croisée prouve-t-elle une paralysie bilatérale du VI ?','Non ; elle peut masquer des ductions complètes.'),('La fixation alternante garantit-elle une stéréoscopie normale ?','Non.'),('Faut-il mesurer la réfraction ?','Oui, même si l’angle est important.'),('Le fond d’œil est-il facultatif ?','Non.'),('Une leucocorie attend-elle le bilan opératoire ?','Non ; elle impose un examen immédiat.'),('La chirurgie guérit-elle automatiquement l’amblyopie ?','Non.'),('Existe-t-il un âge opératoire optimal universel démontré ?','La revue citée ne permet pas de le fixer.'),('Des anomalies verticales peuvent-elles apparaître plus tard ?','Oui.'),('La notice suisse Cyclogyl autorise-t-elle son usage avant un an ?','Non.'),('BOTOX est-il autorisé pour le strabisme du nourrisson ?','Non ; cet usage est hors information professionnelle suisse.'),('Le succès d’alignement permet-il d’arrêter les contrôles ?','Non.'),('Une baisse de vision après intervention doit-elle être banalisée ?','Non ; elle demande une évaluation rapide.')],(1,3,4,6,7,15,18))
l.write()
